/**
 * Keep the V8 cache policy tied to the profile toggle so measurements can
 * attribute the eager code-cache path independently from other optimizations.
 * Electron's startup snapshot is generated by Electron itself and is not
 * changed by this BrowserWindow preference.
 */
export type V8CacheOptions = "code" | "bypassHeatCheckAndEagerCompile";

export function v8CacheOptionsForProfile(enabled: boolean): V8CacheOptions {
    return enabled ? "bypassHeatCheckAndEagerCompile" : "code";
}
